<script setup>
import {computed,ref,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {useArcade} from '../stores/arcade'
import {characterAtStage,enhancementChance,enhancementCost} from '../data/evolutions'
const s=useArcade(),dialog=ref(null),phase=ref('idle'),busy=ref(false),error=ref(''),offer=ref(null),event=ref(null),before=ref(null),after=ref(null)
const title=computed(()=>({confirm:'강화하시겠습니까?',running:'강화 중…',success:'강화에 성공하였습니다',failure:'강화에 실패하였습니다',error:'강화 결과를 확인해 주세요'})[phase.value]??'파트너 강화')
let alive=true,animationTimer,finishAnimation
function effectStyle(i){const a=i*Math.PI/6;return {'--x':50+Math.cos(a)*38,'--y':52+Math.sin(a)*33,'--i':i}}
async function show(){await nextTick();if(alive&&dialog.value&&!dialog.value.open)dialog.value.showModal()}
function close(){dialog.value?.close();phase.value='idle'}
function sync(){if(!alive||busy.value||!dialog.value)return;const e=s.data.pet.enhancement;if(e?.lastResult&&!e.lastResult.acknowledged){event.value={...e.lastResult};before.value=characterAtStage(event.value.character,event.value.fromStage);after.value=characterAtStage(event.value.diglett?'diglett':event.value.character,event.value.toStage);phase.value=event.value.success?'success':'failure';show()}else if(e?.pending){offer.value={...e.pending};before.value={...s.partner};after.value=characterAtStage(s.partner.id,Math.min(3,s.partner.stage+1));error.value='';phase.value='confirm';show()}else close()}
function animationWait(){return new Promise(resolve=>{finishAnimation=resolve;animationTimer=setTimeout(()=>{finishAnimation=null;resolve()},2400)})}
async function accept(){if(busy.value||!offer.value)return;busy.value=true;error.value='';phase.value='running';const id=offer.value.id;try{const results=await Promise.allSettled([s.petAction('enhance',id),animationWait()]);if(!alive)return;if(results[0].status==='rejected')throw results[0].reason;const result=s.data.pet.enhancement.history.find(x=>x.id===id&&x.decision==='accept');if(!result)throw Error('서버의 강화 결과를 다시 확인해 주세요.');event.value={...result};before.value=characterAtStage(result.character,result.fromStage);after.value=characterAtStage(result.diglett?'diglett':result.character,result.toStage);phase.value=result.success?'success':'failure'}catch(e){if(alive){error.value=e.message;phase.value='error'}}finally{if(alive)busy.value=false}}
async function decline(){if(busy.value||!offer.value)return;busy.value=true;error.value='';try{await s.petAction('enhance-decline',offer.value.id)}catch(e){if(alive)error.value=e.message}finally{if(alive){busy.value=false;if(!error.value)sync()}}}
async function acknowledge(){if(busy.value||!event.value)return;busy.value=true;error.value='';try{await s.petAction('enhancement-read',event.value.id)}catch(e){if(alive)error.value=e.message}finally{if(alive){busy.value=false;if(!error.value)sync()}}}
watch(()=>[s.data.pet.enhancement?.pending?.id,s.data.pet.enhancement?.lastResult?.id,s.data.pet.enhancement?.lastResult?.acknowledged,s.partner.id],sync,{flush:'post'})
onMounted(sync);onUnmounted(()=>{alive=false;clearTimeout(animationTimer);finishAnimation?.()})
</script>
<template><dialog ref="dialog" :class="['enhancement-dialog','enhancement-'+phase]" aria-labelledby="enhancement-title" @cancel.prevent><p class="eyebrow">SPOKEMON / PARTNER UPGRADE</p><h2 id="enhancement-title">{{title}}</h2><template v-if="phase==='confirm'"><div class="enhancement-preview"><div><img :src="before?.image" :alt="before?.name"/><b>{{before?.name}}</b></div><span aria-hidden="true">→</span><div><img :src="after?.image" :alt="after?.name"/><b>{{after?.name}}</b></div></div><p>Lv.{{offer?.level}} 강화 기회 · 성공 확률 <strong>{{enhancementChance(s.partner.stage)}}%</strong></p><p class="enhancement-risk">실패하면 디그다로 바뀝니다. 500P로 원래 포켓몬의 1단계로 복구할 수 있어요.<br/>거절하면 현재 형태를 유지하고 이번 강화 기회는 종료됩니다.</p><small>레벨·보유 아이템·구매한 스킨은 보존됩니다. {{enhancementCost(s.partner.id)?'시도마다 1,000 P가 사용되며 실패해도 반환되지 않아요.':'강화 비용은 추가로 들지 않아요.'}}</small><div class="enhancement-actions"><button :disabled="busy||s.data.coins<enhancementCost(s.partner.id)" @click="accept">{{enhancementCost(s.partner.id)?'1,000 P로 강화할게요':'네, 강화할게요'}}</button><button class="light" :disabled="busy" @click="decline">아니요, 유지할게요</button></div></template><template v-else><div class="enhancement-stage"><div v-if="phase==='running'||phase==='success'" class="enhancement-effects" :data-effect="phase==='running'?'fire':'hearts'" aria-hidden="true"><span v-for="i in 12" :key="i" :style="effectStyle(i)">{{phase==='running'?'🔥':'♥'}}</span></div><div v-if="phase==='failure'" class="enhancement-rain" data-effect="rain" aria-hidden="true"><i v-for="i in 35" :key="i" :style="{left:(i*29%100)+'%','--i':i}"></i><span>☁ ☁ ☁</span></div><img :src="phase==='running'||phase==='error'?before?.image:after?.image??before?.image" :alt="phase==='running'||phase==='error'?before?.name:after?.name??before?.name"/></div><template v-if="phase==='running'"><progress aria-label="강화 진행 중"/><p role="status">불꽃 속에서 새로운 힘을 깨우고 있어요…</p></template><template v-else-if="phase==='success'"><h3>{{after?.name}}!</h3><p>강화 {{event?.toStage}}단계가 되었습니다. ♥</p><button :disabled="busy" @click="acknowledge">함께 모험하기 →</button></template><template v-else-if="phase==='failure'"><h3>{{after?.name}}가 되었어요.</h3><p>{{event?.diglett?'디그다로 변했어요. 돌보기 화면에서 500P로 복구할 수 있어요.':'강화 단계가 1단계로 초기화되었습니다.'}}<br/>레벨·보유 아이템·구매한 스킨은 그대로예요.</p><button :disabled="busy" @click="acknowledge">확인</button></template><template v-else-if="phase==='error'"><p>연결 오류를 강화 실패로 처리하지 않습니다.<br/>같은 요청의 서버 결과를 다시 확인해 주세요.</p><button :disabled="busy" @click="accept">결과 다시 확인</button></template></template><p v-if="error" class="notice" role="alert">{{error}}</p></dialog></template>
<style scoped>
.enhancement-dialog{box-sizing:border-box;width:min(580px,calc(100vw - 24px));max-width:none;max-height:91dvh;overflow:auto;padding:25px;background:var(--rpg-paper);color:var(--rpg-ink);border:3px solid var(--rpg-edge);border-radius:18px;box-shadow:inset 0 0 0 4px var(--rpg-bright),0 8px 0 var(--rpg-shadow),0 20px 60px #0005;text-align:center}.enhancement-dialog::backdrop{background:#152338c4;backdrop-filter:blur(4px)}.enhancement-dialog h2{font-size:25px;margin:12px 0 18px}.enhancement-dialog h3{font-size:21px;margin:8px 0}.enhancement-dialog .eyebrow{font-size:10px}.enhancement-dialog p{font-size:13px;line-height:1.9}.enhancement-dialog small{font-size:10px;display:block;line-height:1.8}.enhancement-preview{display:grid;grid-template-columns:1fr 25px 1fr;gap:10px;align-items:center}.enhancement-preview>div{display:flex;flex-direction:column;gap:10px;align-items:center}.enhancement-preview img{width:100%;height:155px;object-fit:contain}.enhancement-preview b{font-size:15px}.enhancement-risk{padding:10px;background:var(--rpg-soft);border:1px solid var(--rpg-mid);border-radius:8px}.enhancement-actions{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:20px}.enhancement-actions button{font-size:13px}.enhancement-stage{position:relative;height:245px;isolation:isolate;overflow:hidden;border-radius:15px;background:radial-gradient(ellipse,var(--rpg-bright),transparent 70%)}.enhancement-stage>img{position:absolute;width:70%;height:185px;object-fit:contain;left:15%;bottom:12px;z-index:1}.enhancement-running .enhancement-stage{background:radial-gradient(ellipse at 50% 80%,#ffb36d88,transparent 72%)}.enhancement-effects{position:absolute;inset:0;z-index:2;pointer-events:none}.enhancement-effects>span{position:absolute;left:calc(var(--x)*1%);top:calc(var(--y)*1%);font-family:'Segoe UI Emoji','Apple Color Emoji',sans-serif;font-size:34px;transform:translate(-50%,-50%);animation:enhancement-fire .5s calc(var(--i)*-.07s) ease-in-out infinite alternate}.enhancement-effects[data-effect='hearts']>span{color:#ee557c;font-size:30px;animation:enhancement-heart 1.4s calc(var(--i)*-.12s) ease-out infinite}.enhancement-rain{position:absolute;inset:0;z-index:3;pointer-events:none}.enhancement-rain>i{position:absolute;width:2px;height:25px;background:linear-gradient(transparent,#81b6ef);top:-30px;animation:enhancement-rain .7s calc(var(--i)*-.031s) linear infinite}.enhancement-rain>span{font-family:'Segoe UI Emoji','Apple Color Emoji',sans-serif;position:absolute;top:0;left:0;right:0;font-size:38px;letter-spacing:20px;color:#7598be}.enhancement-failure .enhancement-stage>img{filter:saturate(.6)}.enhancement-dialog progress{width:75%;height:13px;margin:18px 0 3px}.enhancement-dialog>button{margin:12px 0 5px}@keyframes enhancement-fire{to{transform:translate(-50%,-75%) scale(1.2);opacity:.55}}@keyframes enhancement-heart{to{transform:translate(-50%,-180%) scale(.7);opacity:.1}}@keyframes enhancement-rain{to{transform:translate(-18px,300px)}}@media(prefers-reduced-motion:reduce){.enhancement-effects>span,.enhancement-rain>i{animation:none}.enhancement-rain>i{top:25%}}@media(max-width:600px){.enhancement-dialog{padding:22px 14px}.enhancement-dialog h2{font-size:20px}.enhancement-dialog h3{font-size:18px}.enhancement-preview img{height:120px}.enhancement-preview b{font-size:12px}.enhancement-dialog p{font-size:11px}.enhancement-actions button{font-size:11px}.enhancement-stage{height:220px}.enhancement-stage>img{height:165px}.enhancement-effects>span{font-size:28px}}
</style>
